package com.iha.visa;

import java.time.Instant;
import java.util.Set;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * A visa-related file: uploaded by the patient, generated by the hospital
 * (invitation / appointment letters) or issued by the lawyer (the approved visa).
 */
@Entity
@Table(name = "visa_documents")
public class VisaDocument {

	public static final String PATIENT_UPLOAD = "patient_upload";
	public static final String HOSPITAL_GENERATED = "hospital_generated";
	public static final String LAWYER_ISSUED = "lawyer_issued";

	public static final String HOSPITAL_INVITATION = "hospital_invitation";
	public static final String APPOINTMENT_CONFIRMATION = "appointment_confirmation";
	public static final String APPROVED_VISA = "approved_visa";
	public static final String PASSPORT_PHOTOGRAPH = "passport_photograph";

	/** Categories a patient may upload (the hospital letters are generated by the hospital). */
	public static final Set<String> UPLOADABLE_CATEGORIES = Set.of("passport", PASSPORT_PHOTOGRAPH, "bank_statement",
			"sponsorship_letter", "employer_letter", "companion_passport", "companion_proof_of_relationship");

	@Id
	private UUID id;

	@Column(name = "patient_id", nullable = false, updatable = false)
	private UUID patientId;

	@Column(name = "case_id")
	private UUID caseId;

	@Column(name = "visa_submission_id")
	private UUID visaSubmissionId;

	@Column(name = "hospital_id")
	private UUID hospitalId;

	@Column(nullable = false)
	private String category;

	@Column(nullable = false)
	private String source;

	@Column(name = "requested_by_lawyer", nullable = false)
	private boolean requestedByLawyer;

	@Column(name = "file_name", nullable = false)
	private String fileName;

	@Column(name = "file_path", nullable = false)
	private String filePath;

	@Column(name = "file_size_bytes")
	private Long fileSizeBytes;

	@Column(name = "mime_type")
	private String mimeType;

	@Column(name = "sent_to_patient_at")
	private Instant sentToPatientAt;

	@Column(name = "review_status")
	private String reviewStatus;

	@Column(name = "uploaded_at", nullable = false, updatable = false)
	private Instant uploadedAt;

	protected VisaDocument() {
	}

	VisaDocument(UUID id, UUID patientId, UUID caseId, UUID visaSubmissionId, String category, String fileName,
			String filePath, long fileSizeBytes, String mimeType, boolean requestedByLawyer) {
		this.id = id;
		this.patientId = patientId;
		this.caseId = caseId;
		this.visaSubmissionId = visaSubmissionId;
		this.category = category;
		this.source = PATIENT_UPLOAD;
		this.fileName = fileName;
		this.filePath = filePath;
		this.fileSizeBytes = fileSizeBytes;
		this.mimeType = mimeType;
		this.requestedByLawyer = requestedByLawyer;
		this.uploadedAt = Instant.now();
	}

	/** A hospital letter or lawyer-issued document (until the provider portals are ported: tests and seed data). */
	public static VisaDocument issued(UUID patientId, UUID caseId, UUID hospitalId, String source, String category,
			String fileName, String filePath, String mimeType) {
		VisaDocument doc = new VisaDocument(UUID.randomUUID(), patientId, caseId, null, category, fileName, filePath,
				0, mimeType, false);
		doc.source = source;
		doc.hospitalId = hospitalId;
		doc.sentToPatientAt = Instant.now();
		return doc;
	}

	/** A letter generated in the hospital portal; the patient sees it once the hospital sends it. */
	public static VisaDocument hospitalLetter(UUID patientId, UUID caseId, UUID visaSubmissionId, UUID hospitalId,
			String category, String fileName, String filePath, long fileSizeBytes) {
		VisaDocument doc = new VisaDocument(UUID.randomUUID(), patientId, caseId, visaSubmissionId, category, fileName,
				filePath, fileSizeBytes, "application/pdf", false);
		doc.source = HOSPITAL_GENERATED;
		doc.hospitalId = hospitalId;
		return doc;
	}

	/** Regenerating a letter replaces its file; whether it was sent is kept. */
	public void replaceFile(String fileName, String filePath, long fileSizeBytes) {
		this.fileName = fileName;
		this.filePath = filePath;
		this.fileSizeBytes = fileSizeBytes;
	}

	public void markSentToPatient() {
		this.sentToPatientAt = Instant.now();
	}

	public UUID getHospitalId() {
		return hospitalId;
	}

	void linkTo(UUID caseId, UUID submissionId) {
		this.caseId = caseId;
		this.visaSubmissionId = submissionId;
	}

	public UUID getId() {
		return id;
	}

	public UUID getPatientId() {
		return patientId;
	}

	public UUID getCaseId() {
		return caseId;
	}

	public UUID getVisaSubmissionId() {
		return visaSubmissionId;
	}

	public String getCategory() {
		return category;
	}

	public String getSource() {
		return source;
	}

	public boolean isRequestedByLawyer() {
		return requestedByLawyer;
	}

	public String getFileName() {
		return fileName;
	}

	public String getFilePath() {
		return filePath;
	}

	public Long getFileSizeBytes() {
		return fileSizeBytes;
	}

	public String getMimeType() {
		return mimeType;
	}

	public Instant getSentToPatientAt() {
		return sentToPatientAt;
	}

	public String getReviewStatus() {
		return reviewStatus;
	}

	public Instant getUploadedAt() {
		return uploadedAt;
	}

}
